var a=`1015-thai-fish-cakes`;var t=`world-1015`;var n=`TH`;var s=`southeast-asia`;var o=4;var r=36;var l={en:`Thai Fish Cakes`,ua:`Тайські рибні котлетки`};var h={en:`Thai Fish Cakes is a dish from Thailand prepared with tilapia, thai red curry paste, fish sauce, chicken egg. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Тайські рибні котлетки, страва кухні країни Таїланд, яку готують із таких продуктів: тилапія, червона тайська паста карі, рибний соус, куряче яйце. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var u=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:12,i:[[`tilapia`,600,`g`],[`thai-red-curry-paste`,58,`g`],[`fish-sauce`,20,`ml`],[`chicken-egg`,1,`pcs`],[`green-beans`,100,`g`],[`makrut-lime-leaves`,4,`leaf`]]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:8,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 12 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 12 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:12,i:[[`canola-oil`,100,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:4,i:[[`sweet-chili-sauce`,100,`ml`],[`cucumber`,100,`g`]]}];var d={slug:a,id:t,country:`TH`,region:s,servings:4,minutes:36,title:l,text:h,steps:u};export{n as country,d as default,t as id,r as minutes,s as region,o as servings,a as slug,u as steps,h as text,l as title};